//! Build script (contract §4.1 rule 2, §9.2).
//!
//! The command list comes from the one manifest, `src/contract/ipc_manifest.rs`
//! (included by path — it is self-contained), and is fed to
//! `tauri_build::AppManifest::commands`. With an app manifest, Tauri rejects
//! every app command that no capability grants, so a command that is not in the
//! manifest is not invocable. tauri-build autogenerates `allow-<command>`
//! permissions (with `_` → `-`) under `permissions/autogenerated/`.
//!
//! Capabilities: `capabilities/main.json` always; `capabilities/debug.json`
//! (the debug-only commands, e.g. `app_diagnostics`) only in debug builds.

#[path = "src/contract/ipc_manifest.rs"]
#[allow(dead_code)]
mod ipc_manifest;

fn main() {
    println!("cargo:rerun-if-changed=src/contract/ipc_manifest.rs");
    println!("cargo:rerun-if-changed=capabilities");

    let names: Vec<&'static str> = ipc_manifest::COMMANDS.iter().map(|c| c.name).collect();
    let names: &'static [&'static str] = Box::leak(names.into_boxed_slice());

    let release = std::env::var("PROFILE").as_deref() == Ok("release");
    let capabilities = if release {
        "./capabilities/main.json"
    } else {
        "./capabilities/*.json"
    };

    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(names))
            .capabilities_path_pattern(capabilities),
    )
    .expect("tauri-build failed");
}
